def set_run_font(run, bold: bool = False) -> None:
    run.font.name = "\u5b8b\u4f53"
    run._element.rPr.rFonts.set(qn("w:eastAsia"), "\u5b8b\u4f53")
    run.font.size = Pt(10.5)
    run.bold = bold


def style_paragraph(paragraph) -> None:
    for run in paragraph.runs:
        set_run_font(run, run.bold)


def add_question(document: Document, question: str, answer: str) -> None:
    p = document.add_paragraph()
    q = p.add_run("\u95ee\uff1a" + question)
    set_run_font(q, True)
    p.paragraph_format.space_after = Pt(3)

    p = document.add_paragraph()
    a = p.add_run("\u7b54\uff1a" + answer)
    set_run_font(a)
    p.paragraph_format.first_line_indent = Pt(21)
    p.paragraph_format.space_after = Pt(6)


def main() -> None:
    if not DOC_PATH.exists():
        raise FileNotFoundError(DOC_PATH)

    backup = DOC_PATH.with_suffix(".docx.bak")
    shutil.copy2(DOC_PATH, backup)

    document = Document(DOC_PATH)
    document.add_page_break()

    for heading, qas in SECTIONS:
        document.add_heading(heading, level=1)
        for paragraph in document.paragraphs[-1:]:
            style_paragraph(paragraph)

        for question, answer in qas:
            add_question(document, question, answer)

    document.save(DOC_PATH)
    print(f"updated={DOC_PATH}")
    print(f"backup={backup}")


if __name__ == "__main__":
    main()
